  cap.selfHud=null;
  cap.topLeftRecent.length=0;
  cap.recent.length=0;
  cap.labels.clear();
  cap.lastEventKey='';
  cap.lastEventAt=0;
  S.hitboxBridge.objects.clear();
  S.hitboxBridge.texts.clear();
  S.hitboxBridge.activeTextKey=0;
