function resetGameplayGate(){
  S.gameplayGate={lastPoll:-Infinity,positiveCount:0,confirmedAt:0,ready:false,
    module:null,status:'waiting-runtime',value:null};
}

function gameplayDetectionAllowed(){
  const g=S.gameplayGate,now=performance.now();
  if(now-g.lastPoll<200)return g.ready;
  // Long gaps (background tabs, frozen rendering) must not join old samples.
  if(now-g.lastPoll>1200){g.positiveCount=0;g.ready=false;g.confirmedAt=0}
  g.lastPoll=now;
  let status='waiting-runtime',value=null,M=null;
  try{
    M=moduleHeap();
    if(M?.calledRun&&M.asm&&M.HEAPU8?.length){
      const query=M._cp6_browser_quit_confirmation;
      if(typeof query==='function'){
        const result=query.call(M);
        value=result===1?1:result===0?0:null;
        status=value===1?'positive':value===0?'not-confirmed':'unexpected-result';
      }else status='unavailable';
    }
  }catch{status='unavailable'}
  if(g.module!==M){g.module=M;g.positiveCount=0;g.ready=false;g.confirmedAt=0}
  g.value=value;g.status=status;
  if(value===1){
    g.positiveCount=Math.min(3,g.positiveCount+1);
    if(g.positiveCount>=3&&!g.ready){g.ready=true;g.confirmedAt=Date.now()}
  }else{
    g.positiveCount=0;g.ready=false;g.confirmedAt=0;
  }
  return g.ready;
}

function activateSelfNameDetection(reason){
  if(S.ownerConfirmed||S.nameDetectActive)return;
  S.nameDetectActive=true;
  S.nameDetectStartedAt=Date.now();
  S.nameDetectEvidence=String(reason||'gameplay-hud');
  S.nameDetectErrorShown=false;
  S.bugRejectCount=0;
  S.ownerCandidate=null;
  updateOwnerLabel();
}

function waitForSelfHud(){
  if(S.ownerConfirmed)return;
  S.hudGateCandidate=null;
  S.ownerCandidate=null;
  S.nameDetectStartedAt=0;
  S.nameDetectEvidence='';
  if(S.nameDetectActive){S.nameDetectActive=false;updateOwnerLabel()}
}

function refreshSelfHudFromTopLeftRecent(){
  const cap=S.labelCapture,now=Date.now();
  if(S.ownerConfirmed)return cap.selfHud;
  if(!gameplayDetectionAllowed()){
    waitForSelfHud();
    cap.topLeftRecent.length=0;
    return cap.selfHud;
  }
  const recent=cap.topLeftRecent.filter(r=>now-r.t<1200&&r.t>=S.gameplayGate.confirmedAt).filter(r=>inSelfHudBroadZone(r));
  if(!recent.length){waitForSelfHud();return cap.selfHud;}
  const levelGroups=new Map(),nameGroups=new Map();
  for(const r of recent){
    const m=/^Lvl\.?\s*[:#]?\s*(\d+)$/i.exec(String(r.text).trim());
    if(!m||!inSelfHudLevelZone(r))continue;
    const key=`${m[1]}\0${Math.round(r.x/3)}\0${Math.round(r.y/3)}`;
    const g=levelGroups.get(key)||{level:Number(m[1]),rows:[]};g.rows.push(r);levelGroups.set(key,g);
  }
  for(const r of recent){
    const text=String(r.text).trim();
    if(/^(connecting|logging\s*in|loggin\s*in|loading|ready|play|start)(?:[.!… ]*)$/i.test(text))continue;
    if(!inSelfHudNameZone(r)||!validSelfUsername(text)||looksLikeGuildTag(text))continue;
        const key=`${text}\0${Math.round(r.x/3)}\0${Math.round(r.y/3)}`;
    const g=nameGroups.get(key)||{username:text,rows:[]};g.rows.push(r);nameGroups.set(key,g);
  }
  let best=null;
  for(const lg of levelGroups.values()){
    if(lg.rows.length<2)continue;const lr=lg.rows[lg.rows.length-1];
    for(const ng of nameGroups.values()){
      if(ng.rows.length<2)continue;const nr=ng.rows[ng.rows.length-1];
      const dx=Math.abs(nr.x-lr.x),dy=lr.y-nr.y;
      if(dx>120||dy<18||dy>72||Math.abs(nr.t-lr.t)>250)continue;
      const score=ng.rows.length*5+lg.rows.length*4-dx*.08-Math.abs(dy-34)*.3+Math.max(nr.t,lr.t)*1e-12;
      if(!best||score>best.score)best={score,username:ng.username,level:lg.level,nr,lr,nCount:ng.rows.length,lCount:lg.rows.length};
    }
  }
  if(!best){waitForSelfHud();return cap.selfHud;}
  if(!S.bugWordsReady){waitForSelfHud();return cap.selfHud;}

  // A level alone is also visible at home. Require a fresh, stable name/level
  // pair before treating this as a detectable self HUD. This is evidence from
  // rendered HUD text, not an authoritative game-state flag.
  let gate=S.hudGateCandidate;
  const same=gate&&gate.username===best.username&&gate.level===best.level&&
    Math.abs(gate.x-best.nr.x)<=6&&Math.abs(gate.y-best.nr.y)<=6&&
    Math.abs(gate.lx-best.lr.x)<=6&&Math.abs(gate.ly-best.lr.y)<=6&&now-gate.lastSeen<=1200;
  if(!same){
    waitForSelfHud();
    S.hudGateCandidate={username:best.username,level:best.level,x:best.nr.x,y:best.nr.y,
      lx:best.lr.x,ly:best.lr.y,firstSeen:now,lastSeen:now,lastDraw:Math.min(best.nr.t,best.lr.t),samples:1};
    return cap.selfHud;
  }
  const draw=Math.min(best.nr.t,best.lr.t);
  if(draw>gate.lastDraw){gate.samples++;gate.lastDraw=draw;gate.lastSeen=now}
  if(now-gate.firstSeen<600||gate.samples<3)return cap.selfHud;
  activateSelfNameDetection('internal quit-confirmation signal + stable username/Lvl HUD');

  // Never create a server user from a single transient world label.  The same
  // fixed HUD pair must win repeatedly before an owner is accepted.
  if(S.ownerName && best.username!==S.ownerName){
    return cap.selfHud;
  }
  if(!S.ownerName){
    const c=S.ownerCandidate;
    if(!c||c.username!==best.username||c.level!==best.level){
      S.ownerCandidate={username:best.username,level:best.level,firstSeen:now,lastSeen:now,wins:1};
      return cap.selfHud;
    }
    c.lastSeen=now;c.wins++;
    if(c.wins<2||now-c.firstSeen<180)return cap.selfHud;
    S.ownerName=best.username;
    GM_setValue('marklister_owner',S.ownerName);
  }
  cap.selfHud={username:S.ownerName,guild:null,level:best.level,x:best.lr.x,y:best.lr.y,lastSeen:now,isHud:true,source:'locked-fixed-HUD',confidence:{nameDraws:best.nCount,levelDraws:best.lCount}};
  S.selfHud=cap.selfHud;
  if(!S.ownerConfirmed){S.ownerConfirmed=true;updateOwnerLabel();bootstrap(true)}
  return cap.selfHud;
}

function recordCanvasText(ctx,args){
  const text=String(args?.[0]??'').trim();if(!text)return;
  const cap=S.labelCapture,drawOrder=++cap.drawSeq;
  S.gameCanvas=ctx.canvas||S.gameCanvas;

  // The WASM health-bar hook calls this path for every rendered entity.
  // In normal Display mode keep text only when the first label is a marked user.
  const hb=S.hitboxBridge;
  if(hb.activeTextKey&&hb.activeTextBuffer){
    if(S.selectionMode){
      if(hb.activeTextBuffer.length<6)hb.activeTextBuffer.push(text);
    }else if(markedDisplayActive()){
      if(hb.activeTextBuffer.length===0){
        if(S.listMap.has(text.toLowerCase()))hb.activeTextBuffer.push(text);
        else hb.activeTextRejected=true;
      }else if(!hb.activeTextRejected&&hb.activeTextBuffer.length<6){
        hb.activeTextBuffer.push(text);
      }
    }
  }

  // With the hitbox bridge active, Canvas text is only needed for SELF locking.
  // Once SELF is locked, do not build the expensive world-label fallback.
  if(S.ownerConfirmed&&S.hitboxBridge.patched)return;

  // If SELF is already known and Click User is not active, the fallback only
  // needs marked usernames plus the adjacent guild/Lvl rows.
  if(S.ownerConfirmed&&!S.selectionMode){
    if(!markedDisplayActive())return;
    const lower=text.toLowerCase();
    const relevant=S.listMap.has(lower)||looksLikeGuildTag(text)||/^Lvl\.?\s*[:#]?\s*\d+$/i.test(text);
    if(!relevant)return;
  }

  const now=performance.now(),pt=canvasPoint(ctx,args?.[1],args?.[2]),client=canvasPointToClient(ctx,pt);
  if(!Number.isFinite(client.x)||!Number.isFinite(client.y))return;
  const eventKey=`${text}\0${Math.round(client.x*2)}\0${Math.round(client.y*2)}`;
  if(cap.lastEventKey===eventKey&&now-cap.lastEventAt<5)return;
  cap.lastEventKey=eventKey;cap.lastEventAt=now;
  let textCenterClientX=client.x,textWidthClient=0;
  try{
    const width=Number(ctx.measureText?.(text)?.width)||0;
    const align=String(ctx.textAlign||'start').toLowerCase();
    const dir=String(ctx.direction||'inherit').toLowerCase();
    let dx=0;
    if(align==='left'||(align==='start'&&dir!=='rtl'))dx=width/2;
    else if(align==='right'||(align==='end'&&dir!=='rtl'))dx=-width/2;
    else if(align==='start'&&dir==='rtl')dx=-width/2;
    else if(align==='end'&&dir==='rtl')dx=width/2;
    const cp=canvasPoint(ctx,Number(args?.[1]||0)+dx,Number(args?.[2]||0));
    textCenterClientX=canvasPointToClient(ctx,cp).x;
    const lp=canvasPointToClient(ctx,canvasPoint(ctx,Number(args?.[1]||0),Number(args?.[2]||0)));
    const rp=canvasPointToClient(ctx,canvasPoint(ctx,Number(args?.[1]||0)+width,Number(args?.[2]||0)));
    textWidthClient=Math.abs(rp.x-lp.x);
  }catch{}
  const entry={ctx,text,clientX:client.x,clientY:client.y,textCenterX:textCenterClientX,textWidthClient,t:now,drawOrder,font:String(ctx.font||''),fillStyle:String(ctx.fillStyle??''),strokeStyle:String(ctx.strokeStyle??'')};
  cap.recent.push(entry);
  const cutoff=now-220;
  while(cap.recent.length&&cap.recent[0].t<cutoff)cap.recent.shift();
  if(cap.recent.length>120)cap.recent.splice(0,cap.recent.length-120);

  const selfLevelMatch=/^Lvl\.?\s*[:#]?\s*(\d+)$/i.exec(text);
  // Keep collecting while waiting; a level alone never starts detection.
  if(!S.ownerConfirmed&&client.x<520&&client.y<280){
    cap.topLeftRecent.push({text,x:client.x,y:client.y,t:Date.now(),font:String(ctx.font||''),fillStyle:String(ctx.fillStyle??'')});
    const tc=Date.now()-5000;
    cap.topLeftRecent=cap.topLeftRecent.filter(r=>r.t>=tc).slice(-120);
    refreshSelfHudFromTopLeftRecent();
  }

  const lm=selfLevelMatch;if(!lm)return;
  const level=Number(lm[1]);

  if(!S.ownerConfirmed&&inSelfHudLevelZone(client)){refreshSelfHudFromTopLeftRecent();return}
  if(inSelfHudBroadZone(client))return;

  const previous=[];
  for(let i=cap.recent.length-2;i>=0&&previous.length<8;i--){
    const r=cap.recent[i];
    if(r.ctx!==ctx)continue;
    if(now-r.t>=60)break;
    previous.push(r);
  }
  if(!previous.length)return;

  const p0=previous[0];
  let guildEntry=null,usernameEntry=null;
  if(looksLikeGuildTag(p0.text)){
    guildEntry=p0;usernameEntry=previous[1]||null;
    if(!usernameEntry||looksLikeGuildTag(usernameEntry.text)||textLooksLikeUiNoise(usernameEntry.text))return;
    if(entry.drawOrder-guildEntry.drawOrder>3||guildEntry.drawOrder-usernameEntry.drawOrder>3)return;
  }else{
    usernameEntry=p0;
    if(looksLikeGuildTag(usernameEntry.text)||textLooksLikeUiNoise(usernameEntry.text))return;
    if(entry.drawOrder-usernameEntry.drawOrder>3)return;
  }

  const username=String(usernameEntry.text||'').trim(),guild=guildEntry?.text||null;
  if(!username||username.length>80||!/[A-Za-z0-9_\-]/.test(username)||isBugWord(username))return;
  if(!S.selectionMode&&S.ownerConfirmed&&!S.listMap.has(username.toLowerCase()))return;
  const userDx=Math.abs(usernameEntry.clientX-entry.clientX),userDy=entry.clientY-usernameEntry.clientY;
  if(userDx>120||userDy<1.5||userDy>28)return;
  if(guildEntry){
    const guildDx=Math.abs(guildEntry.clientX-entry.clientX),guildDy=entry.clientY-guildEntry.clientY;
    if(guildDx>120||guildDy<-5||guildDy>12)return;
  }
  if(entry.clientX<-40||entry.clientY<-40||entry.clientX>innerWidth+40||entry.clientY>innerHeight+40)return;

  const data={username,guild,level,x:entry.clientX,y:entry.clientY,levelCenterX:Number.isFinite(entry.textCenterX)?entry.textCenterX:entry.clientX,levelWidth:Number(entry.textWidthClient)||0,usernameX:usernameEntry.clientX,usernameCenterX:Number.isFinite(usernameEntry.textCenterX)?usernameEntry.textCenterX:usernameEntry.clientX,usernameWidth:Number(usernameEntry.textWidthClient)||0,usernameY:usernameEntry.clientY,guildX:guildEntry?.clientX??null,guildCenterX:guildEntry?(Number.isFinite(guildEntry.textCenterX)?guildEntry.textCenterX:guildEntry.clientX):null,guildWidth:guildEntry?(Number(guildEntry.textWidthClient)||0):0,guildY:guildEntry?.clientY??null,lastSeen:Date.now(),source:'contiguous-render-bundle'};
  const key=`${username}\0${level}\0${Math.round(entry.clientX/8)}\0${Math.round(entry.clientY/8)}`;
  cap.labels.set(key,data);
}

function installCanvasCapture(){
  const CTX=PAGE.CanvasRenderingContext2D?.prototype||window.CanvasRenderingContext2D?.prototype;if(!CTX||S.hooked)return;
  for(const method of ['fillText','strokeText']){
    const old=CTX[method];if(typeof old!=='function')continue;
    CTX[method]=new Proxy(old,{apply(target,ctx,args){
      // Deep sleep: after SELF is known, Display is OFF and Click User is not
      // active, avoid even converting every Canvas string.
      const needCapture=worldTrackingActive();
      let text='';
      if(needCapture){
        text=String(args?.[0]??'').trim();
        try{recordCanvasText(ctx,args)}catch{}
      }
      if(method==='fillText'&&S.displayEnabled&&S.listMap.size){
        if(!text)text=String(args?.[0]??'').trim();
        if(S.listMap.has(text.toLowerCase())){
          const oldFill=ctx.fillStyle;
          try{ctx.fillStyle=selectedColorForName(text);return Reflect.apply(target,ctx,args)}
          finally{ctx.fillStyle=oldFill}
        }
      }
      return Reflect.apply(target,ctx,args);
    }});
  }
  S.hooked=true;
}

function visiblePlayers(wantedNames=null){
  const now=Date.now(),cutoff=now-2600,cap=S.labelCapture;
  if(!S.ownerConfirmed)refreshSelfHudFromTopLeftRecent();
  if(now-S.lastLabelCleanupAt>650){
    S.lastLabelCleanupAt=now;
    for(const [k,v] of cap.labels)if(v.lastSeen<cutoff)cap.labels.delete(k);
  }
  const byId=new Map();
  for(const v of cap.labels.values()){
    if(v.lastSeen<cutoff)continue;
    if(wantedNames&&!wantedNames.has(String(v.username||'').toLowerCase()))continue;
    if(inSelfHudBroadZone({x:v.x,y:v.y}))continue;
    if(cap.selfHud&&v.username===cap.selfHud.username&&v.level===cap.selfHud.level)continue;
    const key=`${v.username}\0${v.level}`,old=byId.get(key);
    if(!old||v.lastSeen>old.lastSeen)byId.set(key,v);
  }
  return [...byId.values()];
}

function playerCenter(p){
  // Fallback only. The username's visual centre is often shifted left of the
  // actual flower because florr lays out the guild+level row independently.
  // Use the lower metadata row as the horizontal anchor; this lines up much
  // better with the health bar / flower centre seen in-game.
  const ux=Number.isFinite(p.usernameCenterX)?p.usernameCenterX:(Number.isFinite(p.usernameX)?p.usernameX:p.x);
  const uy=Number.isFinite(p.usernameY)?p.usernameY:p.y;
  const lx=Number.isFinite(p.levelCenterX)?p.levelCenterX:(Number.isFinite(p.x)?p.x:ux);
  const lw=Math.max(0,Number(p.levelWidth)||0);
  let lowerCenter=lx;
  if(Number.isFinite(p.guildCenterX)){
    const gx=p.guildCenterX,gw=Math.max(0,Number(p.guildWidth)||0);
    if(gw>0||lw>0){
      const left=Math.min(gx-gw/2,lx-lw/2),right=Math.max(gx+gw/2,lx+lw/2);
      lowerCenter=(left+right)/2;
    }else lowerCenter=(gx+lx)/2;
  }
  const ly=Number.isFinite(p.y)?p.y:uy+14;
  const gap=Math.max(6,ly-uy);
  const x=Number.isFinite(lowerCenter)?lowerCenter:ux;
  const y=uy-Math.max(13,Math.min(48,gap*1.85));
  const diameter=Math.max(46,Math.min(92,gap*3.0));
  return{x,y,r:diameter,hitR:Math.max(70,diameter+24),source:'label-fallback-meta-center'};
}

function bridgePlayers(){
  const now=performance.now(),out=[];
  for(const [k,v] of S.hitboxBridge.objects){
    if(now-v.t>350){S.hitboxBridge.objects.delete(k);continue}
    if(S.ownerName&&v.username===S.ownerName)continue;
    out.push(v);
  }
  return out;
}
function overlayPlayers(){
  const map=new Map();
  for(const p of bridgePlayers())map.set(`${p.username}\0${p.level}`,p);
  const wanted=S.selectionMode?null:S.listMap;
  // When the bridge is patched it is the authoritative world-position path.
  // Canvas fallback is only maintained if the bridge is unavailable.
  if(!S.hitboxBridge.patched){
    for(const p of visiblePlayers(wanted)){
      const key=`${p.username}\0${p.level}`;
      if(map.has(key))continue;
      const c=playerCenter(p);map.set(key,{...p,cx:c.x,cy:c.y,diameter:c.r,hitDiameter:c.hitR,source:c.source});
    }
  }
  return [...map.values()];
}

function moduleHeap(){return PAGE.Module||window.Module||globalThis.Module||null}
function hbU32(M,a,o=0){return M.HEAPU32[(a+o)>>2]>>>0}
function hbF32(M,a,o=0){return M.HEAPF32[(a+o)>>2]}
function hbF64(M,a,o=0){return M.HEAPF64[(a+o)>>3]}
function clientFromCanvasPoint(x,y,radius){
  const c=S.gameCanvas;if(!c)return null;const rect=c.getBoundingClientRect();if(!rect.width||!rect.height||!c.width||!c.height)return null;
  const sx=rect.width/c.width,sy=rect.height/c.height;
  return{x:rect.left+x*sx,y:rect.top+y*sy,r:radius*Math.sqrt(Math.abs(sx*sy))};
}

const MarklisterWasmImports={
  startCapturingText(key){
    const hb=S.hitboxBridge;
    hb.activeTextKey=0;hb.activeTextBuffer=null;hb.activeTextRejected=false;
    if(!bridgeTrackingActive())return;
    const k=key>>>0;
    hb.texts.delete(k);
    hb.activeTextKey=k;
    hb.activeTextBuffer=[];
  },
  stopCapturingText(){
    const hb=S.hitboxBridge,k=hb.activeTextKey,buf=hb.activeTextBuffer;
    if(k&&buf&&!hb.activeTextRejected&&buf.length){
      hb.texts.set(k,buf);
      trimBridgeTextCache();
    }else if(k){
      hb.texts.delete(k);
    }
    hb.activeTextKey=0;hb.activeTextBuffer=null;hb.activeTextRejected=false;
  },
  drawEntity(world,entity,layer){
    try{
      if(layer===8||!bridgeTrackingActive())return;
      const M=moduleHeap(),V=S.hitboxBridge.vars;if(!M?.HEAPU8||!V.object&&!Number.isFinite(V.object))return;
      const objectPtr=hbU32(M,entity,V.object);if(!objectPtr)return;
      const object2=hbU32(M,objectPtr);if(!object2)return;
      const healthBar=hbU32(M,object2,V.healthBar);if(!healthBar)return;
      const texts=S.hitboxBridge.texts.get(healthBar);if(!texts||texts.length<2)return;
      const levelText=String(texts[texts.length-1]||'').trim();
      const lm=/^Lvl\.?\s*[:#]?\s*(\d+)$/i.exec(levelText);if(!lm)return;
      const username=String(texts[0]||'').trim();if(!username||textLooksLikeUiNoise(username)||looksLikeGuildTag(username)||isBugWord(username))return;
      if(!S.selectionMode&&!S.listMap.has(username.toLowerCase()))return;
      const guild=texts.length>=3?String(texts[1]||'').trim():null;
      const pos=hbU32(M,object2,V.pos);if(!pos)return;
      const x=hbF64(M,pos,V.xValue),y=hbF64(M,pos,V.yValue),size=hbF32(M,objectPtr,V.sizeValue);
      if(!Number.isFinite(x)||!Number.isFinite(y)||!Number.isFinite(size)||size<=0)return;
      const a=hbF32(M,world,0),b=hbF32(M,world,4),c=hbF32(M,world,8),d=hbF32(M,world,12),e=hbF32(M,world,16),f=hbF32(M,world,20);
      if(![a,b,c,d,e,f].every(Number.isFinite))return;
      const px=a*x+c*y+e,py=b*x+d*y+f,scale=(Math.hypot(a,b)+Math.hypot(c,d))/2;
      const client=clientFromCanvasPoint(px,py,size*scale);if(!client)return;
      const visualRadius=Math.max(22,client.r*1.20);
      const diameter=visualRadius*2,hitDiameter=Math.max(70,diameter+22);
      const level=Number(lm[1]);
      S.hitboxBridge.objects.set(`${username}\0${level}`,{username,guild,level,cx:client.x,cy:client.y,diameter,hitDiameter,hitboxRadius:client.r,t:performance.now(),source:'florrkit-hitbox'});
    }catch{}
  }
};

async function installFlorrkitHitboxBridge(){
  if(S.hitboxBridge.status!=='idle')return;
  S.hitboxBridge.status='loading';
  const originalInstantiate=PAGE.WebAssembly.instantiate.bind(PAGE.WebAssembly);
  const originalStreaming=PAGE.WebAssembly.instantiateStreaming?.bind(PAGE.WebAssembly);
  if(originalStreaming){PAGE.WebAssembly.instantiateStreaming=function(){return originalStreaming(new Response())}}
  PAGE.WebAssembly.instantiate=async function(buffer,imports){
    let patched=buffer;
    try{
      if(!(buffer instanceof ArrayBuffer)&&!ArrayBuffer.isView(buffer))return originalInstantiate(buffer,imports);
      if(!PAGE.WabtModule){
        await new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/wabt@1.0.36/index.min.js';sc.onload=resolve;sc.onerror=()=>reject(new Error('WABT load failed'));(document.documentElement||document).appendChild(sc)});
      }
      const wabt=await PAGE.WabtModule();
      const bytes=buffer instanceof ArrayBuffer?buffer:buffer.buffer.slice(buffer.byteOffset,buffer.byteOffset+buffer.byteLength);
      const wasm=wabt.readWasm(bytes,{});wasm.generateNames();wasm.applyNames();let wat=wasm.toText({});
      const V={};
      const toRegex=x=>new RegExp(x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replaceAll('<PARAM>','(.+)').replaceAll('<ANY>','.+'));
      const find=(x,keys)=>{const m=toRegex(x).exec(wat);if(!m)throw new Error('not found: '+keys.join(','));for(let i=1;i<m.length;i++){let v=m[i],n=parseFloat(v);V[keys[i-1]]=Number.isNaN(n)?v:n}};
      const replace=(search,content,name)=>{const re=toRegex(search),m=wat.match(re);if(!m)throw new Error('replace not found: '+name);wat=wat.replace(re,content.replace(/<PARAM_([0-9]+)>/g,'#$1').replaceAll('#','$'))};
      find(`local.tee <ANY>\n                          i32.load offset=<PARAM>\n                          local.set <ANY>\n                          local.get <ANY>\n                          f64.load offset=<ANY>\n                          local.set <ANY>\n                          local.get <ANY>\n                          i32.load offset=<PARAM>`,['object','pos']);
      find(`local.get <ANY>\n                            f64.load offset=<PARAM>\n                            local.set <ANY>\n                            local.get <ANY>\n                            f64.load offset=<PARAM>`,['yValue','xValue']);
      find(`end\n                                call <ANY>\n                                local.set <ANY>\n                                local.get <ANY>\n                                f32.load offset=<PARAM>`,['sizeValue']);
      find(`i32.const 2\n                    i32.shl\n                    i32.add\n                    i32.load\n                    i32.load\n                    local.tee <ANY>\n                    local.get <ANY>\n                    i32.load offset=<ANY>\n                    i32.eq\n                    br_if <ANY>\n                    local.get <ANY>\n                    i32.load offset=<PARAM>\n                    local.tee <ANY>\n                    i32.load8_u offset=<PARAM>`,['healthBar','healthBarTextCount']);
      replace(`  (func `,`\n  (import "marklister" "drawEntity" (func $ml_drawEntity (param i32 i32 i32)))\n  (import "marklister" "startCapturingText" (func $ml_startCapturingText (param i32)))\n  (import "marklister" "stopCapturingText" (func $ml_stopCapturingText))\n  (func `,'imports');
      replace('(local $l53 i64)\n','(local $l53 i64) (local $ml_entity i32)\n','entity local');
      replace(`i32.load\n                    else\n                      local.get <PARAM>\n                    end\n                    local.get `,`i32.load\n                    else\n                      local.get <PARAM_1>\n                    end\n                    local.tee $ml_entity\n                    local.get `,'entity value');
      replace(`f64.load offset=32\n                    f32.demote_f64\n                    call <PARAM>`,`f64.load offset=32\n                    f32.demote_f64\n                    call <PARAM_1>\n                    local.get ${V.worldVar||'$l7'}\n                    local.get $ml_entity\n                    local.get $l12\n                    call $ml_drawEntity`,'draw entity');
      // worldVar is needed by draw hook; discover it with the same stable Florrkit pattern.
      // If the provisional replacement used a fallback, redo from original WAT below.
      if(!V.worldVar){
        // Re-read to keep the edit deterministic and discover worldVar before replacements.
        wat=wasm.toText({});
        find(`local.tee <ANY>\n                          i32.load offset=<PARAM>\n                          local.set <ANY>\n                          local.get <ANY>\n                          f64.load offset=<ANY>\n                          local.set <ANY>\n                          local.get <ANY>\n                          i32.load offset=<PARAM>`,['object','pos']);
        find(`local.get <ANY>\n                            f64.load offset=<PARAM>\n                            local.set <ANY>\n                            local.get <ANY>\n                            f64.load offset=<PARAM>`,['yValue','xValue']);
        find(`end\n                                call <ANY>\n                                local.set <ANY>\n                                local.get <ANY>\n                                f32.load offset=<PARAM>`,['sizeValue']);
        find(`i32.const 2\n                    i32.shl\n                    i32.add\n                    i32.load\n                    i32.load\n                    local.tee <ANY>\n                    local.get <ANY>\n                    i32.load offset=<ANY>\n                    i32.eq\n                    br_if <ANY>\n                    local.get <ANY>\n                    i32.load offset=<PARAM>\n                    local.tee <ANY>\n                    i32.load8_u offset=<PARAM>`,['healthBar','healthBarTextCount']);
        find(`end\n                        local.get <ANY>\n                        local.get <PARAM>\n                        local.get <ANY>\n                        i32.const 255`,['worldVar']);
        replace(`  (func `,`\n  (import "marklister" "drawEntity" (func $ml_drawEntity (param i32 i32 i32)))\n  (import "marklister" "startCapturingText" (func $ml_startCapturingText (param i32)))\n  (import "marklister" "stopCapturingText" (func $ml_stopCapturingText))\n  (func `,'imports');
        replace('(local $l53 i64)\n','(local $l53 i64) (local $ml_entity i32)\n','entity local');
        replace(`i32.load\n                    else\n                      local.get <PARAM>\n                    end\n                    local.get `,`i32.load\n                    else\n                      local.get <PARAM_1>\n                    end\n                    local.tee $ml_entity\n                    local.get `,'entity value');
        replace(`f64.load offset=32\n                    f32.demote_f64\n                    call <PARAM>`,`f64.load offset=32\n                    f32.demote_f64\n                    call <PARAM_1>\n                    local.get ${V.worldVar}\n                    local.get $ml_entity\n                    local.get $l12\n                    call $ml_drawEntity`,'draw entity');
      }
      replace(`local.get <PARAM>\n                    local.get <PARAM>\n                    local.get <PARAM>\n                    f64.load offset=32\n                    call <PARAM>`,`local.get <PARAM_1>\n                    call $ml_startCapturingText\n                    local.get <PARAM_1>\n                    local.get <PARAM_2>\n                    local.get <PARAM_3>\n                    f64.load offset=32\n                    call <PARAM_4>\n                    call $ml_stopCapturingText`,'health bar capture');
      S.hitboxBridge.vars=V;
      patched=wabt.parseWat('marklister.wat',wat).toBinary({}).buffer;
      imports=imports||{};imports.marklister=MarklisterWasmImports;
      S.hitboxBridge.status='patched';S.hitboxBridge.patched=true;
    }catch(err){S.hitboxBridge.status='fallback';S.hitboxBridge.error=String(err?.message||err);console.warn('[Marklister] hitbox bridge fallback:',err)}
    return originalInstantiate(patched,imports);
  };
}

function randomClientToken(){
  const bytes=new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');
}
function getClientToken(){
  if(S.clientToken)return S.clientToken;
  let token=String(GM_getValue(CLIENT_TOKEN_KEY,'')||'').trim();
  if(!/^[a-f0-9]{64}$/i.test(token)){token=randomClientToken();GM_setValue(CLIENT_TOKEN_KEY,token)}
  S.clientToken=token;
  return token;
}
function requestEndpoint(url){try{const u=new URL(url);return u.pathname+u.search}catch{return String(url||'')}}
function requestError(message,code,details={}){const e=new Error(message);e.code=code;Object.assign(e,details);return e}
function gmRequest({method='GET',url,data=null,headers={},timeoutMs=15000,stage='REQUEST'}){
  const requestHeaders={...headers,'X-Marklister-Token':getClientToken()};
  if(data)requestHeaders['Content-Type']='application/json';
  const started=performance.now(),endpoint=requestEndpoint(url);
  return new Promise((resolve,reject)=>GM_xmlhttpRequest({
    method,url,data:data?JSON.stringify(data):undefined,headers:requestHeaders,timeout:timeoutMs,
    onload:r=>{
      const durationMs=performance.now()-started;
      let j=null;try{j=JSON.parse(r.responseText)}catch{}
      if(r.status>=200&&r.status<300)return resolve(j);
      reject(requestError(j?.error||r.responseText||`HTTP ${r.status}`,'HTTP_ERROR',{stage,endpoint,status:r.status,durationMs}));
    },
    onerror:()=>reject(requestError('network error','NETWORK_ERROR',{stage,endpoint,durationMs:performance.now()-started})),
    ontimeout:()=>reject(requestError('timeout','TIMEOUT',{stage,endpoint,durationMs:performance.now()-started,timeoutMs}))
  }))
}
async function api(path,method='GET',data=null,headers={},options={}){
  return gmRequest({method,url:S.serverUrl.replace(/\/$/,'')+path,data,headers,...options})
}
async function bootstrap(force=false){
  if(!S.ownerConfirmed||!S.ownerName)return;
  if(S.bootstrapPromise)return S.bootstrapPromise;
  if(!force&&Date.now()-S.lastSyncAt<2500)return;
  S.lastSyncAt=Date.now();
  const generation=S.ownerDetectionGeneration;
  const endpoint='/api/bootstrap?user='+encodeURIComponent(S.ownerName);
  S.bootstrapPromise=(async()=>{
    let lastError=null;
    for(let attempt=1;attempt<=2;attempt++){
      if(generation!==S.ownerDetectionGeneration)return null;
      try{
        const d=await api(endpoint,'GET',null,{}, {timeoutMs:attempt===1?20000:25000,stage:'BOOT_FETCH'});
        if(generation!==S.ownerDetectionGeneration)return null;
        applyPayload(d);
        return d;
      }catch(e){
        if(generation!==S.ownerDetectionGeneration)return null;
        lastError=e;
        const transient=e?.code==='TIMEOUT'||e?.code==='NETWORK_ERROR';
        if(attempt===1&&transient){await new Promise(r=>setTimeout(r,700));continue}
        console.warn('[Marklister] bootstrap failed',e);
        showError('BOOTSTRAP_FAILED',e?.message||'Unknown bootstrap error',{
          stage:e?.stage||'BOOT_FETCH',
          endpoint:e?.endpoint||endpoint,
          attempt,
          timeoutMs:e?.timeoutMs||'',
          error:e,
          sourceFns:[['bootstrap',bootstrap],['api',api],['gmRequest',gmRequest]]
        });
        return null;
      }
    }
    if(lastError)throw lastError;
    return null;
  })().finally(()=>{if(generation===S.ownerDetectionGeneration)S.bootstrapPromise=null});
  return S.bootstrapPromise;
}
function setList(items){S.entries=Array.isArray(items)?items:[];rebuildDisplayMap()}
async function ensureOwnerReady(timeoutMs=2200){
  const start=performance.now();
  while(performance.now()-start<timeoutMs){
    refreshSelfHudFromTopLeftRecent();
    if(S.ownerConfirmed&&S.ownerName)return true;
    await new Promise(r=>setTimeout(r,80));
  }
  alert(S.nameDetectActive
    ? 'Your username is still being detected. Please try again shortly.'
    : 'Enter the game and wait for your username to appear in the top-left HUD. Click the User label to retry if needed.');
  return false
}
async function addEntry(name,reason,listId){name=String(name||'').trim();if(!name)return alert('Type a user name.');if(isBugWord(name))return alert(name+' is in the Bug Words list and cannot be added as a player.');if(S.addBusy)return;if(S.entries.some(x=>String(x.name||'').toLowerCase()===name.toLowerCase()))return alert(name+' is already in one of your lists. Use Move list instead.');if(!(S.ownerConfirmed&&S.ownerName)){const ok=await ensureOwnerReady();if(!ok)return}reason=String(reason||'').trim()||'blank';listId=Number(listId||S.addListId||defaultList()?.id);if(!listId)return showError('NO_LIST_AVAILABLE','No destination list exists.');S.addBusy=true;try{const d=await api('/api/entry/add','POST',{owner:S.ownerName,name,reason,listId});applyPayload(d);S.selectionMode=false;S.selectedName=null;closeModal();refreshActivity(true)}catch(e){showError('ADD_ENTRY_FAILED',e.message,{target:name})}finally{S.addBusy=false}}
async function updateEntry(id,name,reason){reason=String(reason||'').trim()||'blank';try{const d=await api('/api/entry/update','POST',{owner:S.ownerName,id,name,reason});applyPayload(d);closeModal()}catch(e){showError('UPDATE_ENTRY_FAILED',e.message)}}
async function moveEntry(id,listId){try{const d=await api('/api/entry/move','POST',{owner:S.ownerName,id,listId});applyPayload(d);closeModal()}catch(e){showError('MOVE_ENTRY_FAILED',e.message)}}
async function deleteEntry(id){try{const d=await api('/api/entry/delete','POST',{owner:S.ownerName,id});applyPayload(d)}catch(e){showError('DELETE_ENTRY_FAILED',e.message)}}
async function createList(name,color){
  if(S.createListBusy)return;
  name=String(name||'').trim();
  if(!name)return alert('Type a list name.');
  if(S.lists.some(l=>String(l.name).toLowerCase()===name.toLowerCase()))return alert('A list with that name already exists.');
  if(!S.ownerConfirmed)return alert('Wait for your username to be detected before creating a list.');
  const owner=S.ownerName,generation=S.ownerDetectionGeneration,form=S.modal;
  const button=form?.querySelector('#mlsave'),oldText=button?.textContent;
  S.createListBusy=true;
  if(button){button.disabled=true;button.textContent='Saving...'}
  try{
    const d=await api('/api/list/create','POST',{owner,name,color});
    if(generation!==S.ownerDetectionGeneration)return;
    applyPayload(d);
    if(S.modal===form)closeModal();
  }catch(e){
    if(generation!==S.ownerDetectionGeneration)return;
    if(e.status===409){alert(e.message||'The list could not be created. Please check its name and your list limit.')}
    else showError('CREATE_LIST_FAILED',e.message);
  }finally{
    S.createListBusy=false;
    if(button?.isConnected){button.disabled=false;button.textContent=oldText}
  }
}

async function updateList(id,name,color){try{const d=await api('/api/list/update','POST',{owner:S.ownerName,id,name,color});applyPayload(d);closeModal()}catch(e){showError('UPDATE_LIST_FAILED',e.message)}}
async function deleteList(id){const l=listById(id);if(!l||l.is_default)return;if(!confirm('Delete list '+l.name+' and every entry inside it?'))return;try{const d=await api('/api/list/delete','POST',{owner:S.ownerName,id});applyPayload(d)}catch(e){showError('DELETE_LIST_FAILED',e.message)}}

