function openNewList(){let color=randomUnusedColor();const m=modal(`<div class="ml-modal-title">Make New list</div><div class="ml-field-label">list name</div><div class="ml-row"><input id="mlname" class="ml-input" autocomplete="off" spellcheck="false"><div id="mlcolor" class="ml-color-box" style="background:${color}"></div></div><div style="margin-top:12px"><button id="mlsave" class="ml-addbtn">save</button></div>`);const c=m.querySelector('#mlcolor');c.onclick=()=>chooseColor(color,v=>{color=v;c.style.background=v});m.querySelector('#mlsave').onclick=()=>createList(m.querySelector('#mlname').value.trim(),color);m.querySelector('#mlname').focus()}

function openInviteSquad(){
  if(S.inviteBusy)return;
  const m=modal('<div class="ml-modal-title">Invite squad</div><div id="ml-invite-entries" style="max-height:55vh;overflow:auto"></div>');
  const body=m.querySelector('#ml-invite-entries'),seen=new Set();
  for(const list of S.lists){
    const entries=S.entries.filter(e=>Number(e.list_id)===Number(list.id));
    if(!entries.length)continue;
    const title=document.createElement('div');title.className='ml-field-label';title.textContent=list.name;title.style.color=list.color;body.appendChild(title);
    for(const entry of entries){
      const key=String(entry.name).toLowerCase();if(seen.has(key))continue;seen.add(key);
      const button=document.createElement('button');button.className='ml-mainbtn';button.textContent=entry.name;
      button.title='Invite '+entry.name+' to your squad';button.onclick=()=>inviteSquad(entry.name);body.appendChild(button);
    }
  }
  if(!seen.size){const empty=document.createElement('div');empty.className='ml-field-label';empty.textContent='No saved users. Add a user to a list first.';body.appendChild(empty)}
}
function sendChatEnter(target){
  for(const type of ['keydown','keyup'])target.dispatchEvent(new PAGE.KeyboardEvent(type,{
    key:'Enter',code:'Enter',keyCode:13,which:13,bubbles:true,cancelable:true
  }));
}
function activeGameTextInput(){
  const el=document.activeElement;
  if(!el?.matches?.('#textInputContainer input.textInput')||el.disabled)return null;
  const rect=el.getBoundingClientRect();return rect.width>0&&rect.height>0?el:null;
}
async function inviteSquad(name){
  if(S.inviteBusy)return;
  name=String(name||'').trim();
  if(!name||/[\r\n\u0000-\u001f\u007f]/.test(name))return alert('Invalid username.');
  if(!S.ownerConfirmed)return alert('Enter the game and wait for your username to be detected.');
  const M=moduleHeap();
  try{if(!M?.calledRun||M._cp6_browser_quit_confirmation?.()!==1)return alert('Enter the game before inviting a user.')}catch{return alert('Could not confirm the game state. Please try again in game.')}
  if(activeGameTextInput())return alert('Close the current game text input before inviting a user.');
  const canvas=document.getElementById('canvas');if(!canvas)return;
  S.inviteBusy=true;
  const generation=S.ownerDetectionGeneration;
  closeModal();
  try{
    document.activeElement?.blur?.();canvas.focus();sendChatEnter(canvas);
    let input=null;const started=performance.now();
    while(performance.now()-started<1800){
      await new Promise(r=>setTimeout(r,50));
      if(generation!==S.ownerDetectionGeneration)return;
      input=activeGameTextInput();if(input)break;
    }
    if(!input)throw new Error('Could not open game chat. No invitation command was sent.');
    if(input.value)throw new Error('The game input contains text. It was left unchanged; no invitation was sent.');
    const command='/squad-invite '+name;
    if(input.maxLength>=0&&command.length>input.maxLength)throw new Error('The invitation command exceeds the chat length limit.');
    const setter=Object.getOwnPropertyDescriptor(PAGE.HTMLInputElement.prototype,'value').set;
    setter.call(input,command);input.dispatchEvent(new PAGE.Event('input',{bubbles:true}));
    // Allow the game's input polling to observe the command before Enter.
    await new Promise(r=>setTimeout(r,100));
    if(generation!==S.ownerDetectionGeneration||activeGameTextInput()!==input||input.value!==command)throw new Error('Chat changed before sending. Please check the chat input.');
    sendChatEnter(input);
  }catch(e){alert(e.message)}
  finally{S.inviteBusy=false}
}

function openHelp(){const m=modal('<div class="ml-modal-title">Help</div><div style="font-weight:700;line-height:1.5">Display lister: marklisted users are highlighted.<br>Show list: view / edit / delete your list.<br>Add Marklist: type a name or click a visible player.</div><div class="ml-row" style="margin-top:10px"><button id="madmin" class="ml-cancel">Developer page</button><button id="mclose" class="ml-cancel">Close</button></div>');m.querySelector('#madmin').onclick=()=>{const u=S.serverUrl.replace(/\/$/,'')+'/admin';if(typeof GM_openInTab==='function')GM_openInTab(u,{active:true,insert:true});else window.open(u,'_blank')};m.querySelector('#mclose').onclick=closeModal}

function setupAsciiInputs(scope){
  for(const el of scope.querySelectorAll('.ml-input,.ml-textarea')){
    el.setAttribute('lang','en');
    el.setAttribute('inputmode','text');
    el.addEventListener('compositionstart',e=>e.preventDefault());
    el.addEventListener('beforeinput',e=>{
      if(typeof e.data==='string'&&/[^\x20-\x7E\n\r\t]/.test(e.data))e.preventDefault();
    });
    el.addEventListener('input',()=>{
      const v=el.value.replace(/[^\x20-\x7E\n\r\t]/g,'');
      if(v!==el.value)el.value=v;
    });
    el.addEventListener('paste',e=>{
      const txt=e.clipboardData?.getData('text')??'';
      const clean=txt.replace(/[^\x20-\x7E\n\r\t]/g,'');
      if(clean!==txt){
        e.preventDefault();
        const a=el.selectionStart??el.value.length,b=el.selectionEnd??a;
        el.setRangeText(clean,a,b,'end');
      }
      e.stopPropagation();
    });
  }
}

function editFocusedInputFromKey(e){
  const el=document.activeElement;
  if(!(el instanceof HTMLInputElement||el instanceof HTMLTextAreaElement)||!el.closest('.ml-modal-bg'))return false;
  const key=e.key;
  const a=el.selectionStart??el.value.length,b=el.selectionEnd??a;
  const set=(text,start,end)=>{el.value=text;el.setSelectionRange(start,end);el.dispatchEvent(new Event('input',{bubbles:true}))};
  if((e.ctrlKey||e.metaKey)&&['a','c','v','x'].includes(key.toLowerCase()))return false;
  if(key.length===1&&key.charCodeAt(0)>=0x20&&key.charCodeAt(0)<=0x7e){
    set(el.value.slice(0,a)+key+el.value.slice(b),a+1,a+1);return true;
  }
  if(key==='Backspace'){
    if(a!==b)set(el.value.slice(0,a)+el.value.slice(b),a,a);
    else if(a>0)set(el.value.slice(0,a-1)+el.value.slice(b),a-1,a-1);
    return true;
  }
  if(key==='Delete'){
    if(a!==b)set(el.value.slice(0,a)+el.value.slice(b),a,a);
    else if(a<el.value.length)set(el.value.slice(0,a)+el.value.slice(a+1),a,a);
    return true;
  }
  if(key==='ArrowLeft'){const p=e.shiftKey?b:Math.max(0,a-1);el.setSelectionRange(p,p);return true;}
  if(key==='ArrowRight'){const p=e.shiftKey?b:Math.min(el.value.length,b+1);el.setSelectionRange(p,p);return true;}
  if(key==='Home'){el.setSelectionRange(0,0);return true;}
  if(key==='End'){const p=el.value.length;el.setSelectionRange(p,p);return true;}
  if(key==='Enter'&&el instanceof HTMLTextAreaElement){set(el.value.slice(0,a)+'\n'+el.value.slice(b),a+1,a+1);return true;}
  return ['Tab','Shift','Control','Alt','Meta','CapsLock'].includes(key);
}

function removeOverlayNode(key){const n=S.overlayNodes.get(key);if(!n)return;for(const el of Object.values(n))if(el instanceof Element)el.remove();S.overlayNodes.delete(key)}
function ensureOverlayNode(key,p){
  let n=S.overlayNodes.get(key);if(n)return n;
  const ring=document.createElement('div');ring.className='ml-ring blue';
  const hit=document.createElement('div');hit.className='ml-hit-target';
  const name=document.createElement('div');name.className='ml-target-name';
  const line=document.createElement('div');line.className='ml-line';
  const badge=document.createElement('div');badge.className='ml-badge';
  hit.onclick=e=>{e.preventDefault();e.stopPropagation();const cur=S.overlayNodes.get(key)?.player;if(cur)openReason(cur.username)};
  for(const el of [ring,hit,name,line,badge])S.overlay.appendChild(el);
  n={ring,hit,name,line,badge,player:p};S.overlayNodes.set(key,n);return n;
}
function drawOverlay(){if(!S.overlay)return;const active=S.selectionMode||(S.displayEnabled&&S.listMap.size>0);if(!active){for(const k of [...S.overlayNodes.keys()])removeOverlayNode(k);if(S.hint){S.hint.remove();S.hint=null}return}const players=overlayPlayers(),seen=new Set();for(const p of players){const key=`${p.username}\0${p.level}`,entry=S.listMap.get(p.username.toLowerCase()),marked=!!entry;if(!S.selectionMode&&!marked)continue;seen.add(key);const n=ensureOverlayNode(key,p);n.player=p;const d=Math.max(12,p.diameter||50),hd=Math.max(d,p.hitDiameter||d+20),x=p.cx,y=p.cy,color=marked?(entry.list_color||listById(entry.list_id)?.color||DEFAULT_LIST_COLOR):'#4e99e5';n.ring.style.display=(S.selectionMode||marked)?'block':'none';n.ring.className='ml-ring';n.ring.style.background=hexToRgba(color,marked?.26:.16);n.ring.style.border='3px solid '+hexToRgba(color,.72);n.ring.style.left=x+'px';n.ring.style.top=y+'px';n.ring.style.width=d+'px';n.ring.style.height=d+'px';n.hit.style.display=S.selectionMode?'block':'none';n.hit.style.left=x+'px';n.hit.style.top=y+'px';n.hit.style.width=hd+'px';n.hit.style.height=hd+'px';n.name.style.display=S.selectionMode?'block':'none';n.name.style.left=x+'px';n.name.style.top=(y-d/2-7)+'px';if(n.lastName!==p.username||n.lastList!==entry?.list_name){n.lastName=p.username;n.lastList=entry?.list_name;n.name.textContent=p.username;n.badge.innerHTML=`<div class="small">${esc(entry?.list_name||'select')}</div><div class="big">${esc(p.username)}</div>`}if(S.displayEnabled&&marked){const bx=x+d*.72,by=y-d*.58,dx=bx-x,dy=by-y,len=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)*180/Math.PI;n.line.style.display='block';n.line.style.background=color;n.line.style.left=x+'px';n.line.style.top=y+'px';n.line.style.width=len+'px';n.line.style.transform=`rotate(${ang}deg)`;n.badge.style.display='block';n.badge.style.background=color;n.badge.style.left=(bx-2)+'px';n.badge.style.top=(by-11)+'px'}else{n.line.style.display='none';n.badge.style.display='none'}}for(const k of [...S.overlayNodes.keys()])if(!seen.has(k))removeOverlayNode(k);let h=S.hint;if(S.selectionMode){if(!h||!h.isConnected){h=document.createElement('div');h.className='ml-hint';S.overlay.appendChild(h);S.hint=h}const txt=S.selectedName?'Selected '+S.selectedName:'Click The User . . .';if(h.textContent!==txt)h.textContent=txt}else if(h){h.remove();S.hint=null}}

function overlayLoop(){scheduleOverlayLoop(false)}

function installInputShield(){
  const stopBubble=e=>e.stopPropagation();
  const bindSurface=el=>{
    if(!el)return;
    for(const type of ['pointerdown','pointerup','mousedown','mouseup','click','wheel']){
      el.addEventListener(type,stopBubble,false);
    }
  };
  bindSurface(S.root);
  bindSurface(S.overlay);
  document.addEventListener('pointerdown',e=>{if(e.target instanceof Element&&e.target.closest('.ml-modal-bg'))e.stopPropagation()},false);
  document.addEventListener('click',e=>{if(e.target instanceof Element&&e.target.closest('.ml-modal-bg'))e.stopPropagation()},false);
}
function installKeys(){window.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();cancelCurrentTask();return}if(editFocusedInputFromKey(e)){e.preventDefault();e.stopImmediatePropagation();return}if(e.target instanceof Element&&e.target.closest('.ml-input,.ml-textarea'))return;if(!e.altKey||e.ctrlKey||e.metaKey)return;const k=e.key.toLowerCase();if(k==='d'){e.preventDefault();openSide('display')}else if(k==='s'){e.preventDefault();e.stopImmediatePropagation();if(!e.repeat)openInviteSquad()}else if(k==='l'){e.preventDefault();openSide('show-lists')}else if(k==='a'){e.preventDefault();openAddChoice()}else if(k==='m'){e.preventDefault();openNewList()}},true)}

async function openDeveloperMode(){
  const pw=prompt('Developer password');
  if(pw===null)return;
  try{
    const data=await api('/api/admin','GET',null,{'X-Admin-Password':pw});
    const m=modal('<div class="ml-modal-title">Developer mode</div><div style="max-height:55vh;overflow:auto;background:#4e4a4c;padding:8px;border-radius:3px"><pre id="mdev" style="margin:0;color:#eee;white-space:pre-wrap;word-break:break-word;font:12px Consolas,monospace"></pre></div><button id="mdevclose" class="ml-cancel">Close</button>');
    m.querySelector('#mdev').textContent=JSON.stringify(data,null,2);
    m.querySelector('#mdevclose').onclick=closeModal;
  }catch(e){alert('Developer mode failed: '+e.message)}
}
const UPDATE_SCRIPT_URL='https://raw.githubusercontent.com/Collector4210/Marklister/main/marklister.user.js';
const UPDATE_SNOOZE_KEY='marklister_update_snooze_v1';
function compareReleaseVersions(a,b){
  const parse=v=>/^\d+(?:\.\d+){1,3}$/.test(v)?v.split('.').map(Number):null;
  const x=parse(a),y=parse(b);
  if(!x||!y)return null;
  for(let i=0;i<Math.max(x.length,y.length);i++){
    const d=(x[i]||0)-(y[i]||0);if(d)return Math.sign(d);
  }
  return 0;
}
function releaseVersionFromScript(text){
  const block=/\/\/ ==UserScript==([\s\S]*?)\/\/ ==\/UserScript==/.exec(String(text||''));
  if(!block)return null;
  const namespace=/^\/\/\s*@namespace\s+([^\r\n]+)/m.exec(block[1]);
  if(namespace?.[1].trim()!=='marklister.florr.public')return null;
  const v=/^\/\/\s*@version\s+([^\r\n]+)/m.exec(block[1])?.[1].trim();
  return v&&compareReleaseVersions(v,v)===0?v:null;
}
function fetchReleaseVersion(){
  // Public GitHub request: never attach the Marklister client token.
  return new Promise((resolve,reject)=>GM_xmlhttpRequest({
    method:'GET',url:UPDATE_SCRIPT_URL+'?check='+Date.now(),anonymous:true,timeout:12000,
    onload:r=>{
      if(r.status!==200)return reject(new Error('Update server returned HTTP '+r.status));
      const version=releaseVersionFromScript(r.responseText);
      if(!version)return reject(new Error('Update version could not be verified.'));
      resolve(version);
    },
    onerror:()=>reject(new Error('Update check failed.')),
    ontimeout:()=>reject(new Error('Update check timed out.'))
  }));
}
function showUpdateNotice(version){
  if(document.getElementById('ml-update-notice'))return;
  const box=document.createElement('div');box.id='ml-update-notice';
  box.setAttribute('role','dialog');box.setAttribute('aria-label','Marklister update');
  box.style.cssText='position:fixed;right:20px;bottom:20px;z-index:2147483647;width:290px;max-width:calc(100vw - 40px);box-sizing:border-box;padding:18px;background:#373237;color:#fff;border:2px solid #a88bd9;border-radius:10px;box-shadow:0 8px 30px #0008;font:14px Arial,sans-serif;line-height:1.5;pointer-events:auto';
  const title=document.createElement('strong');title.textContent='Marklister update available';
  const message=document.createElement('p');message.textContent='v'+VERSION.split('-')[0]+' → v'+version+' is available.';
  const install=document.createElement('button');install.textContent='Open update';
  const later=document.createElement('button');later.textContent='Remind me tomorrow';
  for(const button of [install,later])button.style.cssText='cursor:pointer;padding:7px 10px;margin:4px 6px 0 0;border:0;border-radius:5px';
  const dismiss=()=>{GM_setValue(UPDATE_SNOOZE_KEY,{version,until:Date.now()+86400000});box.remove()};
  install.onclick=()=>{
    if(typeof GM_openInTab==='function')GM_openInTab(UPDATE_SCRIPT_URL,{active:true,insert:true});
    else window.open(UPDATE_SCRIPT_URL,'_blank','noopener');
    dismiss();
  };
  later.onclick=dismiss;
  for(const type of ['pointerdown','pointerup','mousedown','mouseup','click','wheel','keydown'])box.addEventListener(type,e=>e.stopPropagation());
  box.append(title,message,install,later);document.documentElement.appendChild(box);
}
async function checkForUpdates(manual=false){
  if(S.updateCheckBusy)return;
  S.updateCheckBusy=true;
  try{
    const version=await fetchReleaseVersion();
    if(compareReleaseVersions(version,VERSION.split('-')[0])!==1){
      if(manual)alert('Marklister is up to date.');return;
    }
    const snooze=GM_getValue(UPDATE_SNOOZE_KEY,null);
    if(!manual&&snooze?.version===version&&Date.now()<snooze.until)return;
    showUpdateNotice(version);
  }catch(e){if(manual)alert(e.message);else console.warn('[Marklister] update check:',e.message)}
  finally{S.updateCheckBusy=false}
}
function scheduleUpdateChecks(){
  setTimeout(()=>checkForUpdates(false),10000);
  setInterval(()=>{if(!document.hidden)checkForUpdates(false)},21600000);
}

function registerMenu(){GM_registerMenuCommand('Marklister: 업데이트 확인',()=>checkForUpdates(true));GM_registerMenuCommand('Marklister: 새로고침',()=>bootstrap(true));GM_registerMenuCommand('Marklister: 사용자 인식 초기화',restartOwnerDetection);GM_registerMenuCommand('Marklister: 개발자 모드',openDeveloperMode);GM_registerMenuCommand('Marklister: 개발자 페이지',()=>{const u=DEFAULT_SERVER_URL+'/admin';if(typeof GM_openInTab==='function')GM_openInTab(u,{active:true,insert:true});else window.open(u,'_blank')})}

function installGlobalErrorCapture(){const ours=v=>{const s=String(v||'').toLowerCase();return s.includes('marklister')||s.includes('userscript')};window.addEventListener('error',e=>{const st=e?.error?.stack||e?.filename||'';if(e?.error&&ours(st))showError('UNCAUGHT_ERROR',e.error.message||e.message,{stage:'UNCAUGHT',error:e.error,stack:e.error.stack||''})});window.addEventListener('unhandledrejection',e=>{const r=e.reason,st=r?.stack||'';if(ours(st))showError('UNHANDLED_REJECTION',r?.message||String(r),{stage:'UNHANDLED_REJECTION',error:r instanceof Error?r:null,stack:st})})}
function start(){S.nameDetectActive=false;S.nameDetectStartedAt=0;installFlorrkitHitboxBridge();createUI();installInputShield();installCanvasCapture();installKeys();installGlobalErrorCapture();registerMenu();scheduleUpdateChecks();refreshBugWords();refreshActivity(true)}
start();
